	@Test
	void exactNegativeKernelsPreserveOuterBagMultiplicityAndSampledZeroStatus() {
		FrontierLayout layout = FrontierLayout.of("x");
		FrontierMaskStrata masks = FrontierMaskStrata.of(layout, 1, new long[] { 1L });
		FrontierStateKey exactParentKey = key(0b001L, masks);
		FrontierStateKey exactChildKey = key(0b011L, masks);
		FrontierStateKey sampledParentKey = key(0b100L, masks);
		FrontierStateKey sampledChildKey = key(0b110L, masks);

		try (FrontierStateArena arena = new FrontierStateArena(256 * 1024L)) {
			arena.declareCanonicalStates(exactParentKey, exactChildKey, sampledParentKey, sampledChildKey);

			FrontierPayloadWriter exactWriter = arena.newPayloadWriter(
					exactParentKey, new int[] { 2 }, new int[] { 0 });
			exactWriter.putExact(0, 0, 3.0d, new long[] { 11L }, 0);
			exactWriter.putExact(0, 1, 4.0d, new long[] { 12L }, 0);
			EvidenceStateRef exactParent = arena.internPayload(
					exactParentKey,
					EvidenceStateSummary.exact(7.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					1,
					exactWriter);

			EvidenceStateRef exactNegative = FrontierLinearTransforms.resolveProjectedOuterKernel(
					arena,
					exactParent,
					exactChildKey,
					2,
					FrontierOuterKernel.NOT_EXISTS,
					(payload, exact, stratum, index) -> payload.exactTermId(stratum, index, 0) == 11L ? 0L : 2L,
					2,
					1.0d);
			assertEquals(EvidenceGuarantee.DATABASE_EXACT, exactNegative.summary().guarantee());
			assertEquals(3.0d, exactNegative.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(exactNegative)) {
				assertEquals(1, payload.exactCount(0));
				assertEquals(3.0d, payload.exactWeight(0, 0));
				assertEquals(11L, payload.exactTermId(0, 0, 0));
			}

			FrontierPayloadWriter sampledWriter = arena.newPayloadWriter(
					sampledParentKey, new int[] { 0 }, new int[] { 1 });
			sampledWriter.putResidual(0, 0, 5.0d, new long[] { 11L }, 0);
			EvidenceStateRef sampledParent = arena.internPayload(
					sampledParentKey,
					unbiased(5.0d, 10.0d, 1.0d, 1.0d),
					FrontierStateOperation.COORDINATED_STAR,
					null,
					null,
					3,
					sampledWriter);

			EvidenceStateRef sampledZero = FrontierLinearTransforms.resolveProjectedOuterKernel(
					arena,
					sampledParent,
					sampledChildKey,
					4,
					FrontierOuterKernel.NOT_EXISTS,
					(payload, exact, stratum, index) -> 1L,
					1,
					1.0d);
			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, sampledZero.summary().guarantee());
			assertEquals(EvidenceZeroStatus.ESTIMATED_ZERO, sampledZero.summary().zeroStatus());
			assertEquals(0.0d, sampledZero.summary().pointRows());
			assertEquals(10.0d, sampledZero.summary().certifiedUpperBound());
			try (FrontierPayloadLease payload = arena.openPayload(sampledZero)) {
				assertEquals(0, payload.exactCount(0));
				assertEquals(0, payload.residualCount(0));
			}
			assertTrue(arena.temporaryReservedBytes() == 0L);
		}
	}

	@Test
	void exactOuterTupleExpansionPreservesMasksAndCoalescesBagDuplicates() {
		FrontierLayout inputLayout = FrontierLayout.of("x");
		FrontierMaskStrata inputMasks = FrontierMaskStrata.of(inputLayout, 1, new long[] { 1L });
		FrontierLayout outputLayout = FrontierLayout.of("x", "y");
		FrontierMaskStrata outputMasks = FrontierMaskStrata.of(outputLayout, 2, new long[] { 1L, 3L });
		FrontierStateKey inputKey = key(0b0001L, inputMasks);
		FrontierStateKey outputKey = key(0b0011L, outputMasks);

		try (FrontierStateArena arena = new FrontierStateArena(256 * 1024L)) {
			arena.declareCanonicalStates(inputKey, outputKey);
			FrontierPayloadWriter inputWriter = arena.newPayloadWriter(
					inputKey, new int[] { 2 }, new int[] { 0 });
			inputWriter.putExact(0, 0, 2.0d, new long[] { 11L }, 0);
			inputWriter.putExact(0, 1, 3.0d, new long[] { 12L }, 0);
			EvidenceStateRef input = arena.internPayload(
					inputKey,
					EvidenceStateSummary.exact(5.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					30,
					inputWriter);

			EvidenceStateRef output = FrontierLinearTransforms.expandOuterMappings(
					arena,
					input,
					outputKey,
					31,
					(payload, exact, stratum, index, emitter) -> {
						long x = payload.exactTermId(stratum, index, 0);
						if (x == 11L) {
							emitter.emit(1, new long[] { x, 21L });
							emitter.emit(1, new long[] { x, 21L });
						} else {
							emitter.emit(0, new long[] { x, 0L });
						}
					},
					2);

			assertEquals(EvidenceGuarantee.DATABASE_EXACT, output.summary().guarantee());
			assertEquals(7.0d, output.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(output)) {
				assertEquals(1, payload.exactCount(0));
				assertEquals(12L, payload.exactTermId(0, 0, 0));
				assertEquals(3.0d, payload.exactWeight(0, 0));
				assertEquals(1, payload.exactCount(1));
				assertEquals(11L, payload.exactTermId(1, 0, 0));
				assertEquals(21L, payload.exactTermId(1, 0, 1));
				assertEquals(4.0d, payload.exactWeight(1, 0));
			}
			assertEquals(0L, arena.temporaryReservedBytes());
		}
	}

	@Test
	void projectionRestrictionAndUnionPreserveFiniteBagSemantics() {
		FrontierLayout inputLayout = FrontierLayout.of("x", "y");
		FrontierMaskStrata inputMasks = FrontierMaskStrata.of(inputLayout, 2, new long[] { 1L, 3L });
		FrontierLayout outputLayout = FrontierLayout.of("x");
		FrontierMaskStrata outputMasks = FrontierMaskStrata.of(outputLayout, 1, new long[] { 1L });
		FrontierStateKey inputKey = key(0b000001L, inputMasks);
		FrontierStateKey projectedKey = key(0b000011L, outputMasks);
		FrontierStateKey restrictedKey = key(0b000111L, outputMasks);
		FrontierStateKey otherKey = key(0b001000L, outputMasks);
		FrontierStateKey unionKey = key(0b001111L, outputMasks);

		try (FrontierStateArena arena = new FrontierStateArena(512 * 1024L)) {
			arena.declareCanonicalStates(inputKey, projectedKey, restrictedKey, otherKey, unionKey);
			FrontierPayloadWriter inputWriter = arena.newPayloadWriter(
					inputKey, new int[] { 1, 2 }, new int[] { 0, 0 });
			inputWriter.putExact(0, 0, 2.0d, new long[] { 11L, 0L }, 0);
			inputWriter.putExact(1, 0, 3.0d, new long[] { 11L, 21L }, 0);
			inputWriter.putExact(1, 1, 4.0d, new long[] { 12L, 22L }, 0);
			EvidenceStateRef input = arena.internPayload(
					inputKey,
					EvidenceStateSummary.exact(9.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					10,
					inputWriter);

			EvidenceStateRef projected = FrontierLinearTransforms.project(
					arena, input, projectedKey, 11, new int[] { 0 });
			assertEquals(EvidenceGuarantee.DATABASE_EXACT, projected.summary().guarantee());
			assertEquals(9.0d, projected.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(projected)) {
				assertEquals(2, payload.exactCount(0));
				assertEquals(11L, payload.exactTermId(0, 0, 0));
				assertEquals(5.0d, payload.exactWeight(0, 0));
				assertEquals(12L, payload.exactTermId(0, 1, 0));
				assertEquals(4.0d, payload.exactWeight(0, 1));
			}

			EvidenceStateRef restricted = FrontierLinearTransforms.restrict(
					arena,
					projected,
					restrictedKey,
					12,
					(payload, exact, stratum, index) -> payload.exactTermId(stratum, index, 0) == 11L);
			assertEquals(5.0d, restricted.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(restricted)) {
				assertEquals(1, payload.exactCount(0));
				assertEquals(11L, payload.exactTermId(0, 0, 0));
				assertEquals(5.0d, payload.exactWeight(0, 0));
			}

			FrontierPayloadWriter otherWriter = arena.newPayloadWriter(
					otherKey, new int[] { 2 }, new int[] { 0 });
			otherWriter.putExact(0, 0, 1.0d, new long[] { 11L }, 0);
			otherWriter.putExact(0, 1, 6.0d, new long[] { 13L }, 0);
			EvidenceStateRef other = arena.internPayload(
					otherKey,
					EvidenceStateSummary.exact(7.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					13,
					otherWriter);

			EvidenceStateRef union = FrontierLinearTransforms.union(
					arena, projected, other, unionKey, 14);
			assertEquals(EvidenceGuarantee.DATABASE_EXACT, union.summary().guarantee());
			assertEquals(16.0d, union.summary().pointRows());
			try (FrontierPayloadLease payload = arena.openPayload(union)) {
				assertEquals(3, payload.exactCount(0));
				assertEquals(11L, payload.exactTermId(0, 0, 0));
				assertEquals(6.0d, payload.exactWeight(0, 0));
				assertEquals(12L, payload.exactTermId(0, 1, 0));
				assertEquals(4.0d, payload.exactWeight(0, 1));
				assertEquals(13L, payload.exactTermId(0, 2, 0));
				assertEquals(6.0d, payload.exactWeight(0, 2));
			}
			assertEquals(0L, arena.temporaryReservedBytes());
		}
	}

	@Test
	void sampledLinearTransformsRemainUnbiasedAndCannotClaimExactZero() {
		FrontierLayout layout = FrontierLayout.of("x");
		FrontierMaskStrata masks = FrontierMaskStrata.of(layout, 1, new long[] { 1L });
		FrontierStateKey sampledKey = key(0b010000L, masks);
		FrontierStateKey projectedKey = key(0b110000L, masks);
		FrontierStateKey zeroKey = key(0b110001L, masks);
		FrontierStateKey exactKey = key(0b000010L, masks);
		FrontierStateKey unionKey = key(0b110010L, masks);

		try (FrontierStateArena arena = new FrontierStateArena(512 * 1024L)) {
			arena.declareCanonicalStates(sampledKey, projectedKey, zeroKey, exactKey, unionKey);
			FrontierPayloadWriter sampledWriter = arena.newPayloadWriter(
					sampledKey, new int[] { 1 }, new int[] { 1 });
			sampledWriter.putExact(0, 0, 2.0d, new long[] { 11L }, 0);
			sampledWriter.putResidual(0, 0, 5.0d, new long[] { 12L }, 0);
			EvidenceStateRef sampled = arena.internPayload(
					sampledKey,
					unbiased(7.0d, 10.0d, 1.0d, 1.0d),
					FrontierStateOperation.COORDINATED_STAR,
					null,
					null,
					20,
					sampledWriter);

			EvidenceStateRef projected = FrontierLinearTransforms.project(
					arena, sampled, projectedKey, 21, new int[] { 0 });
			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, projected.summary().guarantee());
			assertEquals(10.0d, projected.summary().certifiedUpperBound());
			try (FrontierPayloadLease payload = arena.openPayload(projected)) {
				assertEquals(0, payload.exactCount(0));
				assertEquals(2, payload.residualCount(0));
			}

			EvidenceStateRef sampledZero = FrontierLinearTransforms.restrict(
					arena, projected, zeroKey, 22, (payload, exact, stratum, index) -> false);
			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, sampledZero.summary().guarantee());
			assertEquals(EvidenceZeroStatus.ESTIMATED_ZERO, sampledZero.summary().zeroStatus());
			assertEquals(0.0d, sampledZero.summary().pointRows());
			assertEquals(10.0d, sampledZero.summary().certifiedUpperBound());

			FrontierPayloadWriter exactWriter = arena.newPayloadWriter(
					exactKey, new int[] { 1 }, new int[] { 0 });
			exactWriter.putExact(0, 0, 3.0d, new long[] { 13L }, 0);
			EvidenceStateRef exact = arena.internPayload(
					exactKey,
					EvidenceStateSummary.exact(3.0d),
					FrontierStateOperation.EXACT_LEAF,
					null,
					null,
					23,
					exactWriter);

			EvidenceStateRef union = FrontierLinearTransforms.union(
					arena, projected, exact, unionKey, 24);
			assertEquals(EvidenceGuarantee.MEASURE_UNBIASED, union.summary().guarantee());
			assertEquals(10.0d, union.summary().pointRows());
			assertEquals(13.0d, union.summary().certifiedUpperBound());
			try (FrontierPayloadLease payload = arena.openPayload(union)) {
				assertEquals(0, payload.exactCount(0));
				assertEquals(3, payload.residualCount(0));
			}
			assertEquals(0L, arena.temporaryReservedBytes());
		}
	}

	private static FrontierStateKey key(long factors, FrontierMaskStrata masks) {
		return FrontierStateKey.of(
				new long[] { factors },
				masks,
				2L,
				3L,
				4L,
				5L,
				6L,
				7L,
				FrontierLaneFamily.DESIGN,
				0,
				1);
	}

	private static EvidenceStateSummary unbiased(double rows, double upperRows, double ess, double maxWeight) {
		return new EvidenceStateSummary(
				rows,
				0.0d,
				upperRows,
				0.0d,
				EvidenceIntervalKind.NONE,
				1.0d,
				0.0d,
				0.0d,
				ess,
				maxWeight,
				upperRows,
				EvidenceGuarantee.MEASURE_UNBIASED,
				rows == 0.0d ? EvidenceZeroStatus.ESTIMATED_ZERO : EvidenceZeroStatus.POSITIVE,
				"");
	}
